          "line_start": 262,
          "line_end": 266,
          "support": "Dyson singularity nu_crit(E) = s^2 [|E| log^3(Omega/|E|)]^{-1} and resulting sigma_crit ~ s^{-2} log(Omega/omega)."
        }
